// Ambient declarations for image assets imported directly by ui components.
declare module '*.png' {
  const content: string
  export default content
}
declare module '*.avif' {
  const content: string
  export default content
}
declare module '*.webp' {
  const content: string
  export default content
}
declare module '*.jpg' {
  const content: string
  export default content
}
